import{_ as r,o as t,c as a,a5 as o}from"./chunks/framework.BmD0ICqc.js";const c="/study/images/browser/wasm-abi-data-layout.svg",s="/study/images/browser/wasm-arena-allocation.svg",u=JSON.parse('{"title":"WebAssemblyのデータ受け渡しとメモリ確保 — ポインタ・長さ・アリーナ","description":"","frontmatter":{"title":"WebAssemblyのデータ受け渡しとメモリ確保 — ポインタ・長さ・アリーナ","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"browser","summary":"JavaScriptの配列と文字列をWasmの線形メモリに並べる規約と、アリーナが領域を確保・再利用する流れを説明する。","aliases":["WebAssembly","Wasm","ABI","pointer","length","UTF-8","TextEncoder","alignment","padding","arena","bump allocator","alloc","cursor","reset"],"verification":"WebAssembly Core・JavaScript Interface、WHATWG Encoding、ECMAScript、WebAssembly Basic C ABIと照合（2026-11-05）"}},"headers":[],"relativePath":"browser/wasm-data-and-allocation.md","filePath":"browser/wasm-data-and-allocation.md"}'),d={name:"browser/wasm-data-and-allocation.md"};function i(n,e,l,m,b,h){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="webassemblyのデータ受け渡しとメモリ確保-—-ポインタ・長さ・アリーナ" tabindex="-1">WebAssemblyのデータ受け渡しとメモリ確保 — ポインタ・長さ・アリーナ <a class="header-anchor" href="#webassemblyのデータ受け渡しとメモリ確保-—-ポインタ・長さ・アリーナ" aria-label="Permalink to &quot;WebAssemblyのデータ受け渡しとメモリ確保 — ポインタ・長さ・アリーナ&quot;">​</a></h1><p>JavaScriptからWasmの関数に複数の値を渡す方法の一つは、<strong>線形メモリ</strong>にバイト列を書き、関数に<strong>開始位置と長さ</strong>を渡すことです。メモリ上の表現、長さの単位、誰が領域を管理するかまで双方で取り決めます。言語や実行環境の境界で値を渡す規約は <strong>ABI</strong>（Application Binary Interface）の一部です。この実践では二つの <code>i32</code> を引数に取り、先頭からのバイト位置と、読み取る範囲を表します。<a href="https://webassembly.github.io/spec/js-api/#exported-function-exotic-objects" target="_blank" rel="noreferrer">WebAssembly JavaScript Interfaceのエクスポート関数</a>、<a href="/study/browser/webassembly-linear-memory.html">WebAssemblyと線形メモリ</a></p><h2 id="配列は要素数、utf-8はバイト数を渡す" tabindex="-1">配列は要素数、UTF-8はバイト数を渡す <a class="header-anchor" href="#配列は要素数、utf-8はバイト数を渡す" aria-label="Permalink to &quot;配列は要素数、UTF-8はバイト数を渡す&quot;">​</a></h2><table tabindex="0"><thead><tr><th>関数</th><th>開始位置 <code>ptr</code></th><th>長さの単位</th><th>メモリから読む量</th></tr></thead><tbody><tr><td><code>sum_i32(ptr, count)</code></td><td>線形メモリ内のバイト位置</td><td>32ビット整数の個数</td><td><code>count × 4</code> バイト</td></tr><tr><td><code>sum_u8(ptr, byteLength)</code></td><td>線形メモリ内のバイト位置</td><td>符号なしバイトの個数</td><td><code>byteLength</code> バイト</td></tr></tbody></table><p>配列 <code>[10, -2, 32]</code> は、1要素4バイトのリトルエンディアンで連続して並べます。開始位置が1024なら、要素の先頭は1024、1028、1032です。JavaScriptは <code>DataView.setInt32(ptr + i * 4, value, true)</code> で値を書き、Wasmの <code>sum_i32(1024, 3)</code> を呼びます。Wasmは <code>i32.load</code> で各要素を読み、合計の40を返します。実践の <code>i32.add</code> は32ビットで巡回します。<a href="https://tc39.es/ecma262/multipage/structured-data.html#sec-dataview.prototype.setint32" target="_blank" rel="noreferrer">ECMAScriptのDataView.setInt32</a>、<a href="https://webassembly.github.io/spec/core/exec/instructions.html#memory-instructions" target="_blank" rel="noreferrer">WebAssembly Coreのメモリ命令</a>、<a href="https://webassembly.github.io/spec/core/exec/numerics.html#integer-operations" target="_blank" rel="noreferrer">整数の加算</a></p><p>文字列 <code>A猫🎮</code> には、UTF-16コード単位が4個、Unicodeのコードポイントが3個あります。 <code>TextEncoder.encode()</code> の結果はUTF-8の8バイトです。ここでは終端バイトを付けずに並べるので、1040へ書いたときは <code>sum_u8(1040, 8)</code> を呼びます。この関数は <code>i32.load8_u</code> で各バイトを符号なしの値として読み、合計の1322を返します。文字列に戻すには <code>TextDecoder</code> などでUTF-8をデコードします。<a href="https://tc39.es/ecma262/multipage/ecmascript-data-types-and-values.html#sec-ecmascript-language-types-string-type" target="_blank" rel="noreferrer">ECMAScriptのString型</a>、<a href="https://encoding.spec.whatwg.org/#interface-textencoder" target="_blank" rel="noreferrer">WHATWG EncodingのTextEncoder</a>、<a href="/study/data/unicode-and-encoding.html">Unicodeと文字コード</a></p><figure class="study-figure"><img src="'+c+'" alt="配列は1024から3個の32ビット整数を各4バイトで置き、sum_i32に開始位置1024と要素数3を渡す。文字列は1040からUTF-8の8バイトを置き、sum_u8に開始位置1040とバイト数8を渡す。" width="760" height="1100" loading="lazy"><figcaption>配列から先に確保する例です。同じ長さ引数でも、関数によって数える単位が変わります。<a href="/study/images/browser/wasm-abi-data-layout.svg" target="_blank" rel="noopener noreferrer">配列とUTF-8のバイト配置を拡大</a></figcaption></figure><h2 id="バイト列を作る処理とビューを作る処理" tabindex="-1">バイト列を作る処理とビューを作る処理 <a class="header-anchor" href="#バイト列を作る処理とビューを作る処理" aria-label="Permalink to &quot;バイト列を作る処理とビューを作る処理&quot;">​</a></h2><p><code>new DataView(memory.buffer)</code> や <code>new Uint8Array(memory.buffer, ptr, n)</code> は、指定したバッファを参照する<strong>ビュー</strong>を作ります。実践では配列の値を1要素ずつその領域へ書き、文字列は <code>TextEncoder.encode()</code> で作ったバイト列を <code>set()</code> でコピーします。その後のWasm関数の呼び出しで渡すのは開始位置と長さです。関数内のload命令は、JavaScriptが書いた線形メモリを参照します。<a href="https://tc39.es/ecma262/multipage/structured-data.html#sec-structured-data" target="_blank" rel="noreferrer">ECMAScriptのTypedArrayとDataView</a>、<a href="https://encoding.spec.whatwg.org/#interface-textencoder" target="_blank" rel="noreferrer">WHATWG EncodingのTextEncoder</a></p><p>構造体も渡す場合は、フィールドの型と順番、各フィールドの開始位置、パディング、構造体全体のサイズを合わせます。C/C++からコンパイルする場合、<code>int32_t*</code> のようなポインタ引数と長さ引数を持つ関数は、この実践と同様の形で扱えます。構造体のレイアウトや引数・戻り値の渡し方は、そのビルドが採用するABIとエクスポートされたインターフェースに従います。<a href="https://github.com/WebAssembly/tool-conventions/blob/main/BasicCABI.md#data-representation" target="_blank" rel="noreferrer">WebAssembly Basic C ABI</a></p><h2 id="allocは空き領域の先頭を進める" tabindex="-1">allocは空き領域の先頭を進める <a class="header-anchor" href="#allocは空き領域の先頭を進める" aria-label="Permalink to &quot;allocは空き領域の先頭を進める&quot;">​</a></h2><p><strong>アリーナ</strong>は、寿命の近いデータをまとめて置く領域です。実践ではメモリのバイト位置1024から始め、次に使える位置を <code>cursor</code> に記録します。この位置を進めながら領域を切り出す方法を <strong>bump allocator</strong> と呼びます。 <code>alloc(size)</code> の中では次の順に処理します。</p><ol><li>現在の <code>cursor</code> を8の倍数まで切り上げ、今回の先頭候補 <code>start</code> を求めます。</li><li><code>size</code> が正で、<code>start</code> から現在のメモリ末尾までに収まるかを調べます。</li><li>収まれば <code>cursor</code> を <code>start + size</code> へ進め、<code>start</code> を返します。収まらなければ <code>0</code> を返し、<code>cursor</code> はその位置にとどまります。</li></ol><p>最初の配列は <code>alloc(12)</code> で1024から始まり、<code>cursor</code> は1036になります。次の <code>alloc(8)</code> は1036を1040へ切り上げるため、間に4バイトの<strong>パディング</strong>が生まれます。文字列用の領域は1040〜1047、次の <code>cursor</code> は1048です。この8バイト境界は教材の確保規約です。Wasmのロード命令には非整列アクセスも定義されているので、型のレイアウトやアロケータの規約と命令の挙動を区別して読みます。<a href="https://webassembly.github.io/spec/core/syntax/instructions.html#memory-instructions" target="_blank" rel="noreferrer">WebAssembly Coreのメモリ命令とアライメント</a></p><h2 id="確保とmemory-growとresetを分ける" tabindex="-1">確保とmemory.growとresetを分ける <a class="header-anchor" href="#確保とmemory-growとresetを分ける" aria-label="Permalink to &quot;確保とmemory.growとresetを分ける&quot;">​</a></h2><p>実践の <code>alloc</code> は現在あるメモリの範囲で確保し、<code>memory.grow(1)</code> は別の操作として呼びます。例えば <code>cursor = 1048</code>、メモリが1ページの状態では、末尾まで64,488バイトです。 <code>alloc(65_536)</code> は <code>0</code> を返します。1ページ追加して131,072バイトになれば、同じ大きさを確保して <code>cursor</code> を66,584まで進められます。拡張時に既存のバイトは同じ位置に残ります。JavaScript側では、この実践の非共有・固定長バッファが切り離されるので、<code>memory.buffer</code> から新しいビューを作ります。<a href="https://webassembly.github.io/spec/core/exec/runtime.html#memory-instances" target="_blank" rel="noreferrer">WebAssembly Coreのメモリインスタンス</a>、<a href="https://webassembly.github.io/spec/js-api/#memories" target="_blank" rel="noreferrer">JavaScript InterfaceのMemory</a></p><figure class="study-figure"><img src="'+s+'" alt="アリーナは開始位置1024から配列12バイトと4バイトのパディングを挟んでUTF-8の8バイトを置き、次の位置は1048になる。1ページでは65536バイトの追加確保に失敗する。メモリを2ページへ拡張すると同じ確保が成功し、リセットは次の位置を1024へ戻す。" width="760" height="1140" loading="lazy"><figcaption>領域の切り出し、メモリ自体の拡張、まとめて再利用するための位置の巻き戻しを分けます。<a href="/study/images/browser/wasm-arena-allocation.svg" target="_blank" rel="noopener noreferrer">アリーナの状態変化を拡大</a></figcaption></figure><p><code>reset()</code> は <code>cursor</code> を1024に戻します。それまで切り出した領域はまとめて再利用できる状態になり、個別に <code>free</code> する手順はありません。バイト列やページ数は保持されます。古い位置には次のデータが書かれるので、リセットを境に以前のポインタと長さの組は使えなくなると取り決めます。内容の消去が必要なら、再利用とは別に該当範囲への上書きが必要です。</p><h2 id="どの範囲を読んでよいかを確かめる" tabindex="-1">どの範囲を読んでよいかを確かめる <a class="header-anchor" href="#どの範囲を読んでよいかを確かめる" aria-label="Permalink to &quot;どの範囲を読んでよいかを確かめる&quot;">​</a></h2><p>Wasmのload命令が検査するのは、アクセスが<strong>線形メモリ全体</strong>に収まるかです。配列の最後を越えた位置が線形メモリ内にあれば、ロード自体は実行されます。実践の読み取り関数は開始位置が1024以上かつ <code>cursor</code> 以下かを確かめ、残りバイト数から読める個数の上限を求めます。例えば4バイトの要素なら、<code>count</code> を <code>(cursor - ptr) / 4</code> の整数部分と比べます。範囲外の引数ではWasmがトラップし、JavaScript側では <code>WebAssembly.RuntimeError</code> になります。<a href="https://webassembly.github.io/spec/core/exec/instructions.html#memory-instructions" target="_blank" rel="noreferrer">WebAssembly Coreのメモリ命令</a>、<a href="https://webassembly.github.io/spec/js-api/#errors" target="_blank" rel="noreferrer">JavaScript Interfaceのエラー対応</a></p><p>この検査で確かめられる範囲は、アリーナの先頭から <code>cursor</code> までです。例えば配列の開始位置1024に対して誤って要素数6を渡すと、24バイトが収まるため、パディングと文字列まで読み取ります。実践では、Wasmが領域の確保とリセットを管理し、JavaScriptは返された開始位置と実際に書いた長さを組にして、次のリセットまで使います。確保ごとに境界を検査するには領域の開始位置・サイズを、リセットをまたいだ古い参照を検査するには確保の世代も記録します。</p><h2 id="実践との対応" tabindex="-1">実践との対応 <a class="header-anchor" href="#実践との対応" aria-label="Permalink to &quot;実践との対応&quot;">​</a></h2><p>ブラウザで配列と文字列を送り、確保前後の <code>cursor</code> と先頭のずれ、線形メモリに並んだバイト、Wasmの戻り値を確認できます。1ページ分の確保、明示的な拡張、リセットもそれぞれ実行します。<a href="/study/practice/browser/wasm-abi-observation.html">配列・文字列とアリーナの実験</a></p><p>複数のWorkerが同じメモリを読み書きする場合は、誰が書き込み、いつ読めるかを決めます。その順序は<a href="/study/browser/shared-memory-atomics.html">Web Workerと共有メモリの同期</a>で扱います。</p>',24)])])}const g=r(d,[["render",i]]);export{u as __pageData,g as default};
